IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b500968b4fd6734bc3f60f39efc6105c99e3b320cf52df7c600524149572a7cd' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner AND a.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;END $functions$;DO $absent$ BEGIN IF to_regprocedure('folha_privado.custo_operacional_autorizar_v3(uuid)') IS NOT NULL OR to_regprocedure('folha_privado.relatorio_operacional_v3(uuid,date,date,text,uuid)') IS NOT NULL OR to_regprocedure('folha_privado.mapa_operacional_calcular_v3(uuid,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_custos_operacionais_contexto_v3(uuid,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_horas_admin_contexto_v3(uuid)') IS NOT NULL OR to_regprocedure('public.fn_folha_ausencias_contexto_v3(date,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_dia_contexto_v3(date,uuid,uuid,text)') IS NOT NULL OR to_regprocedure('public.fn_folha_destinos_contexto_v3()') IS NOT NULL OR to_regprocedure('public.fn_folha_equipa_horas_contexto_v3(date,uuid)') IS NOT NULL THEN RAISE EXCEPTION 'ADDON_PRESENT_OR_PARTIAL';END IF;END $absent$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_operacional_contextos_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_operacional_contextos_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_operacional_contextos_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_operacional_contextos_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_operacional_contextos_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;CREATE FUNCTION public.fn_folha_dia_contexto_v3(p_data date,p_obra_id uuid,p_person_id uuid,p_kind text DEFAULT 'primeline') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $day$
DECLARE u public.utilizadores;c public.colaboradores;e public.folha_externos;ev public.folha_avaliacoes_diarias;ref jsonb;reference jsonb;records jsonb;refs jsonb;all_count integer;own boolean;can_write boolean;cut date;
BEGIN
 u:=folha_privado.ator();IF p_data IS NULL OR NOT isfinite(p_data) OR p_person_id IS NULL OR p_kind IS NULL OR p_kind NOT IN('primeline','external') THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;IF NOT EXISTS(SELECT 1 FROM public.obras WHERE id=p_obra_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: tenant obra' USING ERRCODE='42501';END IF;PERFORM folha_privado.destino_autorizar_v3(p_person_id,p_obra_id,p_kind,false);
 IF p_kind='primeline' THEN SELECT * INTO c FROM public.colaboradores WHERE id=p_person_id AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;own:=c.utilizador_id=u.id AND (SELECT count(*) FROM public.colaboradores WHERE utilizador_id=u.id AND empresa_id=u.empresa_id)=1;
  IF NOT folha_privado.admin() AND NOT folha_privado.elegivel_equipa(p_person_id,p_data) AND NOT own AND NOT EXISTS(SELECT 1 FROM public.folha_registos WHERE colaborador_id=p_person_id AND obra_id=p_obra_id AND data=p_data) AND NOT EXISTS(SELECT 1 FROM public.folha_referencias WHERE colaborador_id=p_person_id AND origem_obra_id=p_obra_id AND data=p_data AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: âmbito da pessoa' USING ERRCODE='42501';END IF;
  SELECT * INTO ev FROM public.folha_avaliacoes_diarias WHERE colaborador_id=p_person_id AND data=p_data AND empresa_id=u.empresa_id;SELECT avaliacao_diaria_data_ativacao INTO cut FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id;
  IF ev.referencia_estado='capturada' THEN ref:=jsonb_build_object('referencia_estado','capturada','expected_minutes',ev.expected_minutes,'horario_snapshot',ev.horario_snapshot,'identity',ev.id);
  ELSIF cut IS NOT NULL THEN ref:=folha_privado.diaria_referencia(p_person_id,p_data);ELSE ref:=jsonb_build_object('referencia_estado','pendente','referencia_motivo','mecanismo_diario_nao_ativado');END IF;
  reference:=CASE WHEN ref->>'referencia_estado'='capturada' THEN jsonb_build_object('confirmed',true,'version_id',coalesce(ref->>'identity',ref->>'jornada_versao_id',ref->>'horario_versao_id'),'effective_from',p_data,'effective_to',p_data+1,'day',jsonb_build_object('day_type',coalesce(ref->'horario_snapshot'->>'day_type','prevista'),'expected_minutes',ref->'expected_minutes','intervals',ref->'horario_snapshot'->'intervals')) ELSE jsonb_build_object('confirmed',false,'reason',ref->>'referencia_motivo') END;
  can_write:=c.data_admissao<=p_data AND (c.data_saida IS NULL OR c.data_saida>p_data) AND (folha_privado.adm_operacional() OR u.funcao='encarregado' AND (folha_privado.elegivel_equipa(p_person_id,p_data) OR own) OR own AND u.funcao IN('diretor_obra','adjunto','preparador'));
 ELSE SELECT * INTO e FROM public.folha_externos WHERE id=p_person_id AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: externo' USING ERRCODE='42501';END IF;reference:=NULL;can_write:=(e.ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.externo_id=p_person_id AND f.obra_id=p_obra_id AND f.data=p_data AND f.empresa_id=u.empresa_id)) AND (folha_privado.adm_operacional() OR u.funcao IN('encarregado','diretor_obra')) AND (EXISTS(SELECT 1 FROM public.folha_externos_dias WHERE externo_id=p_person_id AND obra_id=p_obra_id AND data=p_data) OR EXISTS(SELECT 1 FROM public.folha_externos_permanencias WHERE externo_id=p_person_id AND obra_id=p_obra_id AND inicio<=p_data AND (fim IS NULL OR fim>p_data)));
 END IF;
 can_write:=coalesce(can_write,false) AND p_data<=(now() AT TIME ZONE 'Europe/Lisbon')::date AND (p_data>=(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR folha_privado.adm_operacional() OR p_kind='external' AND u.funcao='diretor_obra');
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.obra_id),'[]') INTO records FROM public.folha_registos f WHERE f.empresa_id=u.empresa_id AND f.data=p_data AND CASE WHEN p_kind='primeline' THEN f.colaborador_id=p_person_id ELSE f.externo_id=p_person_id END AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=f.obra_id AND utilizador_id=u.id AND papel=u.funcao));
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO refs FROM public.folha_referencias r WHERE r.empresa_id=u.empresa_id AND r.data=p_data AND CASE WHEN p_kind='primeline' THEN r.colaborador_id=p_person_id ELSE r.externo_id=p_person_id END AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=r.origem_obra_id AND utilizador_id=u.id AND papel=u.funcao));
 SELECT count(*) INTO all_count FROM (SELECT id FROM public.folha_registos WHERE data=p_data AND CASE WHEN p_kind='primeline' THEN colaborador_id=p_person_id ELSE externo_id=p_person_id END UNION ALL SELECT id FROM public.folha_referencias WHERE data=p_data AND CASE WHEN p_kind='primeline' THEN colaborador_id=p_person_id ELSE externo_id=p_person_id END) q;
 RETURN jsonb_build_object('version',3,'person_id',p_person_id,'kind',p_kind,'work_id',p_obra_id,'date',p_data,'name',coalesce(c.nome,e.nome),'server_date',(now() AT TIME ZONE 'Europe/Lisbon')::date,'records',records,'references',refs,'hidden_record_count',all_count-jsonb_array_length(records)-jsonb_array_length(refs),'reference',reference,'reference_edit_capability',false,'expected_daily_revision',coalesce(ev.revision,0),'can_write',can_write,'requires_reason',p_data<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR p_kind='external' AND u.funcao='diretor_obra','can_report_faltou',u.funcao='encarregado' AND p_kind='primeline' AND NOT coalesce(own,false) AND all_count=0 AND p_data BETWEEN (now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND (now() AT TIME ZONE 'Europe/Lisbon')::date AND EXISTS(SELECT 1 FROM public.quadro_equipa_permanencias WHERE colaborador_id=p_person_id AND obra_id=p_obra_id AND empresa_id=u.empresa_id AND inicio<=p_data AND (fim IS NULL OR fim>p_data)) AND NOT EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p_person_id AND data=p_data),'has_absence',p_kind='primeline' AND EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p_person_id AND data=p_data));
END $day$;
CREATE FUNCTION public.fn_folha_destinos_contexto_v3() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $works$
DECLARE u public.utilizadores;works jsonb;BEGIN u:=folha_privado.ator();IF NOT folha_privado.admin() AND u.funcao NOT IN('encarregado','diretor_obra','adjunto','preparador') THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'number',o.numero,'name',o.nome,'status',o.situacao) ORDER BY o.numero),'[]') INTO works FROM public.obras o WHERE o.empresa_id=u.empresa_id AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis r WHERE r.obra_id=o.id AND r.utilizador_id=u.id AND r.papel=u.funcao));RETURN jsonb_build_object('version',3,'works',works);END $works$;
REVOKE ALL ON FUNCTION public.fn_folha_dia_contexto_v3(date,uuid,uuid,text),public.fn_folha_destinos_contexto_v3() FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.fn_folha_dia_contexto_v3(date,uuid,uuid,text),public.fn_folha_destinos_contexto_v3() TO authenticated;
CREATE FUNCTION public.fn_folha_equipa_horas_contexto_v3(p_data date,p_obra_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $team$
DECLARE u public.utilizadores;b jsonb;person record;people jsonb:='[]';BEGIN
 u:=folha_privado.ator();b:=public.fn_folha_horas_contexto_v3(p_data,p_obra_id);
 FOR person IN SELECT person_id,kind FROM (SELECT (x->>'person_id')::uuid person_id,'primeline'::text kind FROM jsonb_array_elements(b->'rows') x UNION SELECT (x->>'person_id')::uuid,'external' FROM jsonb_array_elements(b->'external_rows') x UNION SELECT coalesce(colaborador_id,externo_id),CASE WHEN colaborador_id IS NULL THEN 'external' ELSE 'primeline' END FROM public.folha_referencias WHERE empresa_id=u.empresa_id AND origem_obra_id=p_obra_id AND data=p_data UNION SELECT coalesce(colaborador_id,externo_id),CASE WHEN colaborador_id IS NULL THEN 'external' ELSE 'primeline' END FROM public.folha_registos WHERE empresa_id=u.empresa_id AND obra_id=p_obra_id AND data=p_data) q ORDER BY kind,person_id LOOP
  people:=people||jsonb_build_array(public.fn_folha_dia_contexto_v3(p_data,p_obra_id,person.person_id,person.kind));
 END LOOP;RETURN jsonb_build_object('version',3,'date',p_data,'work_id',p_obra_id,'people',people,'works',public.fn_folha_destinos_contexto_v3()->'works','base',b);
END $team$;
REVOKE ALL ON FUNCTION public.fn_folha_equipa_horas_contexto_v3(date,uuid) FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.fn_folha_equipa_horas_contexto_v3(date,uuid) TO authenticated;
CREATE FUNCTION public.fn_folha_horas_admin_contexto_v3(p_obra_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $admin$
DECLARE u public.utilizadores;works jsonb;people jsonb;providers jsonb:='[]';
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() AND u.funcao NOT IN('diretor_obra','adjunto','preparador') THEN RAISE EXCEPTION 'PERMISSION_DENIED: revisão administrativa' USING ERRCODE='42501';END IF;
 IF p_obra_id IS NOT NULL THEN PERFORM folha_privado.custo_operacional_autorizar_v3(p_obra_id);END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.nome,'number',o.numero,'status',o.situacao) ORDER BY o.numero),'[]') INTO works FROM public.obras o WHERE o.empresa_id=u.empresa_id AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.obra_responsaveis r WHERE r.obra_id=o.id AND r.utilizador_id=u.id AND r.papel=u.funcao));
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.nome,'role',c.funcao,'inactive',c.data_saida IS NOT NULL) ORDER BY c.nome,c.id),'[]') INTO people FROM public.colaboradores c WHERE c.empresa_id=u.empresa_id AND folha_privado.admin();
 IF p_obra_id IS NOT NULL THEN SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'name',f.nome) ORDER BY f.nome),'[]') INTO providers FROM public.fornecedores f WHERE f.empresa_id=u.empresa_id AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.subempreitadas s WHERE s.obra_id=p_obra_id AND s.fornecedor_id=f.id) OR EXISTS(SELECT 1 FROM public.folha_externos e JOIN public.folha_registos r ON r.externo_id=e.id WHERE r.empresa_id=u.empresa_id AND r.obra_id=p_obra_id AND e.fornecedor_id=f.id));END IF;
 RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'works',works,'people',people,'providers',providers,'can_monthly_read',folha_privado.admin(),'can_monthly_write',folha_privado.adm_operacional(),'can_read_work',p_obra_id IS NOT NULL,'can_view_hr_costs',folha_privado.admin(),'can_approve_hr_cost',folha_privado.adm_operacional(),'can_associate',folha_privado.adm_operacional(),'can_read_external',p_obra_id IS NOT NULL AND u.funcao<>'preparador','can_view_operational_costs',p_obra_id IS NOT NULL,'financial_effect',false);
END $admin$;
CREATE FUNCTION public.fn_folha_ausencias_contexto_v3(p_inicio date,p_fim date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $absence$
DECLARE u public.utilizadores;rows jsonb;
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() THEN RAISE EXCEPTION 'PERMISSION_DENIED: mapa administrativo' USING ERRCODE='42501';END IF;IF p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>62 THEN RAISE EXCEPTION 'DATE_RANGE_INVALID';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('person_name',c.nome,'controlled_report',r.id IS NOT NULL,'origin_work_id',r.obra_id,'origin_work_name',o.nome,'reported_by',r.ator_id,'author_name',actor.nome,'reported_at',r.at) ORDER BY a.data,a.id),'[]') INTO rows FROM public.ausencias a JOIN public.colaboradores c ON c.id=a.colaborador_id AND c.empresa_id=u.empresa_id LEFT JOIN LATERAL(SELECT h.* FROM public.folha_historico h WHERE h.empresa_id=u.empresa_id AND h.person_id=a.colaborador_id AND h.action='absence_report' AND h.depois->>'id'=a.id::text ORDER BY h.at,h.id LIMIT 1) r ON true LEFT JOIN public.obras o ON o.id=r.obra_id AND o.empresa_id=u.empresa_id LEFT JOIN public.utilizadores actor ON actor.id=r.ator_id AND actor.empresa_id=u.empresa_id WHERE a.data BETWEEN p_inicio AND p_fim;
 RETURN jsonb_build_object('version',3,'from',p_inicio,'to',p_fim,'absences',rows,'can_classify',folha_privado.adm_operacional(),'financial_effect',false);
END $absence$;
REVOKE ALL ON FUNCTION public.fn_folha_horas_admin_contexto_v3(uuid),public.fn_folha_ausencias_contexto_v3(date,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_horas_admin_contexto_v3(uuid),public.fn_folha_ausencias_contexto_v3(date,date) TO authenticated;
CREATE FUNCTION folha_privado.custo_operacional_autorizar_v3(p_obra_id uuid) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $scope$
DECLARE u public.utilizadores;BEGIN u:=folha_privado.ator();IF NOT EXISTS(SELECT 1 FROM public.obras WHERE id=p_obra_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: empresa/obra' USING ERRCODE='42501';END IF;IF NOT folha_privado.admin() AND NOT(u.funcao IN('diretor_obra','adjunto','preparador') AND EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=p_obra_id AND utilizador_id=u.id AND papel=u.funcao)) THEN RAISE EXCEPTION 'PERMISSION_DENIED: custo operacional' USING ERRCODE='42501';END IF;END $scope$;
CREATE FUNCTION public.fn_folha_custos_operacionais_contexto_v3(p_obra_id uuid,p_competencia date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $aggregate$
DECLARE c jsonb;days jsonb;BEGIN PERFORM folha_privado.custo_operacional_autorizar_v3(p_obra_id);c:=folha_privado.mapa_operacional_calcular_v3(p_obra_id,p_competencia);
 SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.date),'[]') INTO days FROM(SELECT x->>'date' date,coalesce(sum((x->>'minutes')::integer) FILTER(WHERE x->>'kind'='primeline'),0)::integer internal_minutes,coalesce(sum((x->>'minutes')::integer) FILTER(WHERE x->>'kind'='external'),0)::integer external_minutes,count(*) FILTER(WHERE x->>'kind'='primeline' AND x->>'provisional_estimate' IS NULL)::integer pending_groups,count(*) FILTER(WHERE x->>'kind'='primeline' AND x->>'valuation_status'='pendente_de_valorizacao')::integer hr31_pending_groups,sum((x->>'provisional_estimate')::numeric) FILTER(WHERE x->>'kind'='primeline') known_estimate,CASE WHEN count(*) FILTER(WHERE x->>'kind'='primeline' AND x->>'provisional_estimate' IS NULL)=0 THEN sum((x->>'provisional_estimate')::numeric) FILTER(WHERE x->>'kind'='primeline') END provisional_estimate FROM jsonb_array_elements(c->'groups') x GROUP BY x->>'date') d;
 RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'month',p_competencia,'scope','work_aggregate','daily',days,'provisional_minutes',c->'provisional_minutes','consolidated_minutes',c->'consolidated_minutes','external_minutes',c->'external_minutes','provisional_estimate',c->'provisional_estimate','known_provisional_estimate',c->'known_provisional_estimate','pending_valuation_groups',c->'pending_valuation_days','financial_effect',false,'he_cost_calculated',false,'legacy_costs_included',false,'individual_costs_included',false);
END $aggregate$;

CREATE FUNCTION folha_privado.relatorio_operacional_v3(p_obra_id uuid,p_inicio date,p_fim date,p_kind text DEFAULT NULL,p_fornecedor_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $report$
DECLARE u public.utilizadores;records jsonb;legacy jsonb;days jsonb;weeks jsonb;months jsonb;
BEGIN
 u:=folha_privado.ator();IF p_obra_id IS NULL OR p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>30 OR p_kind IS NOT NULL AND p_kind NOT IN('primeline','external') THEN RAISE EXCEPTION 'REPORT_RANGE_INVALID: até 31 dias';END IF;
 PERFORM folha_privado.custo_operacional_autorizar_v3(p_obra_id);
 IF p_fornecedor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fornecedores WHERE id=p_fornecedor_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: fornecedor' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision,'date',f.data,'work_id',f.obra_id,'person_id',coalesce(f.colaborador_id,f.externo_id),'kind',CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END,'name',coalesce(c.nome,e.nome),'provider_id',e.fornecedor_id,'provider_name',provider.nome,'intervals',f.intervals,'minutes',f.minutes,'open',f.estado='open','corrected',EXISTS(SELECT 1 FROM public.folha_historico h WHERE h.empresa_id=u.empresa_id AND h.person_id=coalesce(f.colaborador_id,f.externo_id) AND h.kind=CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END AND h.obra_id=f.obra_id AND h.data=f.data AND h.antes IS NOT NULL AND h.antes<>'null'::jsonb),'last_changed_at',f.atualizado_em,'changed_by',f.atualizado_por) ORDER BY f.data,f.id),'[]') INTO records
 FROM public.folha_registos f LEFT JOIN public.colaboradores c ON c.id=f.colaborador_id AND c.empresa_id=u.empresa_id LEFT JOIN public.folha_externos e ON e.id=f.externo_id AND e.empresa_id=u.empresa_id LEFT JOIN public.fornecedores provider ON provider.id=e.fornecedor_id AND provider.empresa_id=u.empresa_id
 WHERE f.empresa_id=u.empresa_id AND f.obra_id=p_obra_id AND f.data BETWEEN p_inicio AND p_fim AND (p_kind IS NULL OR p_kind='primeline' AND f.colaborador_id IS NOT NULL OR p_kind='external' AND f.externo_id IS NOT NULL) AND (p_fornecedor_id IS NULL OR e.fornecedor_id=p_fornecedor_id);

 SELECT records||coalesce(jsonb_agg(jsonb_build_object('id',r.id,'revision',r.revision,'date',r.data,'work_id',r.associada_obra_id,'origin_work_id',r.origem_obra_id,'source','reference','reference_id',r.id,'original_reference',r.referencia_original,'reference_type',r.tipo,'association_pending',r.associada_obra_id IS NULL,'person_id',coalesce(r.colaborador_id,r.externo_id),'kind',CASE WHEN r.colaborador_id IS NULL THEN 'external' ELSE 'primeline' END,'name',coalesce(c.nome,e.nome),'provider_id',e.fornecedor_id,'provider_name',provider.nome,'intervals',r.intervals,'minutes',r.minutes,'open',r.open,'corrected',r.revision>1,'last_changed_at',r.atualizado_em,'changed_by',r.atualizado_por) ORDER BY r.data,r.id),'[]') INTO records FROM public.folha_referencias r LEFT JOIN public.colaboradores c ON c.id=r.colaborador_id AND c.empresa_id=u.empresa_id LEFT JOIN public.folha_externos e ON e.id=r.externo_id AND e.empresa_id=u.empresa_id LEFT JOIN public.fornecedores provider ON provider.id=e.fornecedor_id AND provider.empresa_id=u.empresa_id WHERE r.empresa_id=u.empresa_id AND (r.associada_obra_id=p_obra_id OR r.associada_obra_id IS NULL AND r.origem_obra_id=p_obra_id) AND r.data BETWEEN p_inicio AND p_fim AND (p_kind IS NULL OR p_kind='primeline' AND r.colaborador_id IS NOT NULL OR p_kind='external' AND r.externo_id IS NOT NULL) AND (p_fornecedor_id IS NULL OR e.fornecedor_id=p_fornecedor_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('source','legacy','original',to_jsonb(p)) ORDER BY p.data,p.id),'[]') INTO legacy FROM public.ponto_pessoal_obra p WHERE p.empresa_id=u.empresa_id AND p.obra_id=p_obra_id AND p.data BETWEEN p_inicio AND p_fim AND p_kind IS DISTINCT FROM 'external' AND p_fornecedor_id IS NULL;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.date,x.person_id),'[]') INTO days FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,r->>'date' date,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',r->>'date') x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.week,x.person_id),'[]') INTO weeks FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('week',(r->>'date')::date)::date week,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('week',(r->>'date')::date)::date) x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.month_start,x.person_id),'[]') INTO months FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('month',(r->>'date')::date)::date month_start,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('month',(r->>'date')::date)::date) x;
 RETURN jsonb_build_object('version',3,'committed',false,'work_id',p_obra_id,'from',p_inicio,'to',p_fim,'records',records,'daily',days,'weekly',weeks,'monthly',months,'legacy',legacy,'legacy_included_in_totals',false,'financial_effect',false,'classification_included',false);
END $report$;
CREATE FUNCTION folha_privado.mapa_operacional_calcular_v3(p_obra_id uuid,p_competencia date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $map$
DECLARE u public.utilizadores;r jsonb;g record;f jsonb;c public.folha_conferencias_mensais;a public.folha_avaliacoes_diarias;rate public.folha_custos_hora_versoes;ref jsonb;approval_cache jsonb:='{}';source_ok boolean;consolidated boolean;expected integer;actual integer;status text;amount numeric;money boolean;groups jsonb:='[]';minutes_provisional integer:=0;minutes_consolidated integer:=0;minutes_external integer:=0;known_amount numeric:=0;unknown_cost integer:=0;known_days integer:=0;
BEGIN
 u:=folha_privado.ator();IF p_competencia IS NULL OR NOT isfinite(p_competencia) OR extract(day FROM p_competencia)<>1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;r:=folha_privado.relatorio_operacional_v3(p_obra_id,p_competencia,(p_competencia+interval '1 month')::date-1,NULL,NULL);money:=true;
 FOR g IN SELECT x->>'kind' kind,(x->>'person_id')::uuid person_id,(x->>'date')::date date,jsonb_agg(x ORDER BY x->>'id') records,sum((x->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(r->'records') x GROUP BY x->>'kind',x->>'person_id',x->>'date' ORDER BY x->>'date',x->>'person_id' LOOP
  amount:=NULL;status:='horas_apenas';consolidated:=false;rate:=NULL;
  IF g.kind='external' THEN minutes_external:=minutes_external+g.minutes;
  ELSE
   IF NOT(approval_cache ? g.person_id::text) THEN SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND competencia=p_competencia;source_ok:=false;IF c.estado='validada_para_integracao' AND c.fingerprint=c.validacao_fingerprint THEN source_ok:=(folha_privado.conferencia_calcular(g.person_id,p_competencia)->>'fingerprint')=c.fingerprint;END IF;approval_cache:=approval_cache||jsonb_build_object(g.person_id::text,source_ok);END IF;
   SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND competencia=p_competencia;
   consolidated:=coalesce((approval_cache->>g.person_id::text)::boolean,false) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.records) fact WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.snapshot->'days') day CROSS JOIN LATERAL jsonb_array_elements(day->'facts') item WHERE item->>'id'=fact->>'id' AND item->>'revision'=fact->>'revision'));
   IF consolidated THEN minutes_consolidated:=minutes_consolidated+g.minutes;ELSE minutes_provisional:=minutes_provisional+g.minutes;END IF;
   SELECT * INTO a FROM public.folha_avaliacoes_diarias WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date;IF a.referencia_estado='capturada' THEN expected:=a.expected_minutes;ELSE ref:=folha_privado.diaria_referencia(g.person_id,g.date);expected:=CASE WHEN ref->>'referencia_estado'='capturada' THEN (ref->>'expected_minutes')::integer END;END IF;
   SELECT coalesce(sum(x.minutes),0)::integer INTO actual FROM (SELECT minutes FROM public.folha_registos WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date UNION ALL SELECT minutes FROM public.folha_referencias WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date) x;
   IF expected IS NOT NULL AND actual>expected THEN status:='pendente_de_valorizacao';
   ELSIF expected IS NULL THEN status:='referencia_diaria_pendente';
   ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(g.records) x WHERE coalesce((x->>'association_pending')::boolean,false) OR (x->>'open')::boolean) THEN status:='factos_pendentes';
   ELSIF NOT money THEN status:='horas_apenas';
   ELSE SELECT * INTO rate FROM public.folha_custos_hora_versoes WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND vigente_desde<=g.date AND (vigente_ate IS NULL OR vigente_ate>g.date);IF rate.id IS NULL THEN status:='custo_hora_rh_pendente';ELSE status:='estimativa_provisoria';amount:=round(g.minutes*rate.custo_hora/60,2);known_amount:=known_amount+amount;known_days:=known_days+1;END IF;END IF;
   IF amount IS NULL THEN unknown_cost:=unknown_cost+1;END IF;
  END IF;
  groups:=groups||jsonb_build_array(jsonb_build_object('person_id',g.person_id,'kind',g.kind,'date',g.date,'minutes',g.minutes,'records',g.records,'consolidated',consolidated,'valuation_status',status,'provisional_estimate',amount,'rate_id',CASE WHEN amount IS NOT NULL THEN rate.id END,'rate_revision',CASE WHEN amount IS NOT NULL THEN rate.revision END,'valuation_blocks_rh',false));
 END LOOP;
 RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'month',p_competencia,'groups',groups,'provisional_minutes',minutes_provisional,'consolidated_minutes',minutes_consolidated,'external_minutes',minutes_external,'provisional_estimate',CASE WHEN money AND unknown_cost=0 AND known_days>0 THEN known_amount END,'known_provisional_estimate',CASE WHEN money AND known_days>0 THEN known_amount END,'valuation_scope','internal_hours_only','pending_valuation_days',unknown_cost,'financial_effect',false,'legacy_costs_included',false,'he_cost_calculated',false);
END $map$;
CREATE OR REPLACE FUNCTION public.fn_folha_conferencia_contexto_v3(p_colaborador_id uuid,p_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;c public.folha_conferencias_mensais;s jsonb;history jsonb;
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() OR NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p_colaborador_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: conferência interna' USING ERRCODE='42501';END IF;
 s:=folha_privado.conferencia_calcular(p_colaborador_id,p_competencia);SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p_colaborador_id AND competencia=p_competencia;
 SELECT coalesce(jsonb_agg(x.event ORDER BY x.event->>'at',x.event->>'id'),'[]') INTO history FROM (
 SELECT to_jsonb(h)||jsonb_build_object('domain','conference','author_name',a.nome) event FROM public.folha_conferencia_historico h LEFT JOIN public.utilizadores a ON a.id=h.ator_id AND a.empresa_id=u.empresa_id WHERE h.empresa_id=u.empresa_id AND h.conferencia_id=c.id
 UNION ALL SELECT to_jsonb(h)||jsonb_build_object('domain','facts','author_name',a.nome) FROM public.folha_historico h LEFT JOIN public.utilizadores a ON a.id=h.ator_id AND a.empresa_id=u.empresa_id WHERE h.empresa_id=u.empresa_id AND h.person_id=p_colaborador_id AND h.kind='primeline' AND h.data>=p_competencia AND h.data<(p_competencia+interval '1 month')::date
 UNION ALL SELECT to_jsonb(h)||jsonb_build_object('domain','daily','author_name',actor.nome,'revision',h.depois->'revision') FROM public.folha_gestao_historico h JOIN public.folha_avaliacoes_diarias d ON d.id=h.entidade_id AND d.empresa_id=h.empresa_id LEFT JOIN public.utilizadores actor ON actor.id=h.ator_id AND actor.empresa_id=u.empresa_id WHERE h.empresa_id=u.empresa_id AND d.colaborador_id=p_colaborador_id AND d.data>=p_competencia AND d.data<(p_competencia+interval '1 month')::date AND h.action IN('daily_reference_correct','daily_he_validate','daily_he_disregard')
 UNION ALL SELECT to_jsonb(h)||jsonb_build_object('domain','reference','author_name',actor.nome) FROM public.folha_referencias_historico h JOIN public.folha_referencias r ON r.id=h.referencia_id AND r.empresa_id=h.empresa_id LEFT JOIN public.utilizadores actor ON actor.id=h.ator_id AND actor.empresa_id=u.empresa_id WHERE h.empresa_id=u.empresa_id AND r.colaborador_id=p_colaborador_id AND r.data>=p_competencia AND r.data<(p_competencia+interval '1 month')::date
) x;
 RETURN jsonb_build_object('version',3,'committed',false,'person_id',p_colaborador_id,'month',p_competencia,'snapshot',s,'conference',CASE WHEN c.id IS NULL THEN NULL ELSE to_jsonb(c) END,'history',history,'he_policy','HR-27','financial_effect',false,'conference_write_capability',folha_privado.adm(),'expected_monthly_minutes',s->'expected_minutes','expected_coverage_state',CASE WHEN (s->>'unknown_reference_days')::integer=0 THEN 'known' ELSE 'pending' END);
END $context$;
CREATE OR REPLACE FUNCTION public.fn_folha_referencias_contexto_v3(p_data date,p_obra_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;rows jsonb;BEGIN u:=folha_privado.ator();PERFORM folha_privado.obra(p_obra_id);IF p_data IS NULL THEN RAISE EXCEPTION 'DATE_REQUIRED';END IF;SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO rows FROM public.folha_referencias r WHERE r.empresa_id=u.empresa_id AND r.data=p_data AND (r.origem_obra_id=p_obra_id OR r.associada_obra_id=p_obra_id);RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'date',p_data,'records',rows,'can_associate',folha_privado.adm_operacional(),'history',(SELECT coalesce(jsonb_agg(to_jsonb(h)||jsonb_build_object('author_name',actor.nome) ORDER BY h.at,h.id),'[]') FROM public.folha_referencias_historico h JOIN public.folha_referencias r ON r.id=h.referencia_id AND r.empresa_id=h.empresa_id LEFT JOIN public.utilizadores actor ON actor.id=h.ator_id AND actor.empresa_id=u.empresa_id WHERE h.empresa_id=u.empresa_id AND r.data=p_data AND (r.origem_obra_id=p_obra_id OR r.associada_obra_id=p_obra_id))); END $context$;
CREATE OR REPLACE FUNCTION public.fn_folha_custo_hora_contexto_v3(p_colaborador_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;versions jsonb;history jsonb;rev integer;
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() OR NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p_colaborador_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: custo RH' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(v)||jsonb_build_object('approver_name',(SELECT nome FROM public.utilizadores WHERE id=v.aprovado_por AND empresa_id=u.empresa_id)) ORDER BY revision),'[]'),coalesce(max(revision),0) INTO versions,rev FROM public.folha_custos_hora_versoes v WHERE v.empresa_id=u.empresa_id AND v.colaborador_id=p_colaborador_id;
 SELECT coalesce(jsonb_agg(to_jsonb(h)||jsonb_build_object('author_name',(SELECT nome FROM public.utilizadores WHERE id=h.ator_id AND empresa_id=u.empresa_id),'reason',h.depois->'new'->>'motivo') ORDER BY h.at,h.id),'[]') INTO history FROM public.folha_custos_hora_historico h JOIN public.folha_custos_hora_versoes v ON v.id=h.nova_versao_id AND v.empresa_id=h.empresa_id WHERE h.empresa_id=u.empresa_id AND v.colaborador_id=p_colaborador_id;
 RETURN jsonb_build_object('version',3,'person_id',p_colaborador_id,'expected_revision',rev,'versions',versions,'history',history,'can_approve',folha_privado.adm_operacional(),'financial_effect',false);
END $context$;
REVOKE ALL ON FUNCTION folha_privado.custo_operacional_autorizar_v3(uuid),folha_privado.relatorio_operacional_v3(uuid,date,date,text,uuid),folha_privado.mapa_operacional_calcular_v3(uuid,date),public.fn_folha_custos_operacionais_contexto_v3(uuid,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_custos_operacionais_contexto_v3(uuid,date) TO authenticated;
DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
